// Preparar nombre del archivo y ejecutar pg_dump en un solo paso.
// Las credenciales libpq viven en /data/backup-config.env (mount read-only
// de ./backup.env en el host, gitignored). La password NUNCA aparece en
// el codigo, en este JSON ni en los datos de ejecucion.
const { execSync } = require('child_process');

const now = new Date();
const ts = now.toISOString().replace(/[:.]/g, '-').slice(0, 19);
const filename = `gymbro-backup-${ts}.dump`;
const backupPath = `/data/backups/${filename}`;
const startedAt = now.toISOString();

let stdout = '', stderr = '', exitCode = 0;
const cmd = '. /data/backup-config.env && pg_dump -Fc -f ' + JSON.stringify(backupPath);

try {
  stdout = execSync(cmd, { encoding: 'utf8', shell: '/bin/sh', maxBuffer: 10 * 1024 * 1024 });
} catch (e) {
  stdout = e.stdout ? e.stdout.toString() : '';
  stderr = e.stderr ? e.stderr.toString() : String(e.message || e);
  exitCode = typeof e.status === 'number' ? e.status : 1;
}

return [{
  json: {
    filename,
    backupPath,
    startedAt,
    stdout,
    stderr,
    exitCode
  }
}];

// Verificar generación y archivo:
//  1) pg_dump finalizó con código de salida 0
//  2) el archivo existe
//  3) su tamaño supera 1 KB
//  4) corresponde a ESTA ejecución (mtime >= startedAt - 5s), no a un archivo anterior
const fs = require('fs');
const params = $input.item.json;

let exists = false, size = 0, verifyError = '', mtimeMs = 0;
try {
  const st = fs.statSync(params.backupPath);
  exists = st.isFile();
  size = st.size;
  mtimeMs = st.mtimeMs;
} catch (e) {
  verifyError = String(e.message || e);
}

const startedMs = Date.parse(params.startedAt) || 0;
const freshEnough = mtimeMs >= startedMs - 5000;

const genOk = params.exitCode === 0;
const fileOk = exists && size > 1024;
const isValid = genOk && fileOk && freshEnough && !verifyError;

let error = '';
if (!isValid) {
  if (!genOk) error = `pg_dump falló (exitCode=${params.exitCode}): ${params.stderr || 'sin detalle'}`;
  else if (verifyError) error = `No se puede leer el archivo: ${verifyError}`;
  else if (!exists) error = 'El archivo de backup no existe tras la ejecución';
  else if (size <= 1024) error = `Archivo inválido o muy pequeño: ${size} bytes`;
  else if (!freshEnough) error = 'El archivo es anterior a esta ejecución (mtime no coincide)';
}

return [{
  json: {
    ...params,
    fileExists: exists,
    fileSizeBytes: size,
    fileSizeMB: (size / 1024 / 1024).toFixed(2),
    fileMtime: mtimeMs ? new Date(mtimeMs).toISOString() : '',
    genOk,
    fileOk,
    freshEnough,
    isValid,
    error
  }
}];

// Verificar contenido legible del dump: pg_restore --list (cuenta objetos).
// pg_restore --list solo lee el archivo; NO conecta a la base principal.
// Esta comprobación exige exitCode 0 y objetos > 0: NO usarlo como sustituto de una restauración real.
const { execSync } = require('child_process');
const params = $input.item.json;

let objectCount = 0, stderr = '', exitCode = 0;
try {
  const out = execSync('pg_restore --list ' + JSON.stringify(params.backupPath), { encoding: 'utf8', shell: '/bin/sh', maxBuffer: 10 * 1024 * 1024 });
  objectCount = out.split('\n').filter(l => l.trim().length > 0).length;
} catch (e) {
  stderr = e.stderr ? e.stderr.toString() : String(e.message || e);
  exitCode = typeof e.status === 'number' ? e.status : 1;
}

const contentOk = exitCode === 0 && objectCount > 0;

return [{ json: { ...params, objectCount, restoreExitCode: exitCode, restoreError: stderr, contentOk } }];

// Backup exitoso: armar el reporte y anexar la linea al log de informes
const fs = require('fs');
const params = $input.item.json;
const stamp = new Date().toISOString();

const report = {
  resultado: 'backup_exitoso',
  filename: params.filename,
  backupPath: params.backupPath,
  fileSizeMB: params.fileSizeMB,
  fileSizeBytes: params.fileSizeBytes,
  objetosEnDump: params.objectCount,
  timestamp: stamp,
  startedAt: params.startedAt
};

console.log('[WF2] Backup verificado exitosamente:', JSON.stringify(report));

const line = `[${stamp}] resultado=backup_exitoso | archivo=${report.filename} | gen=OK | verificacion_archivo=OK | contenido=OK(objetos=${report.objetosEnDump}) | error=-\n`;
let logWritten = false, logError = '';
try {
  fs.appendFileSync('/data/informes/backup-log.txt', line, 'utf8');
  logWritten = true;
} catch (e) {
  logError = String(e.message || e);
}

return [{ json: { ...report, logWritten, logError } }];

// Backup fallido: armar el reporte y anexar la linea al log de informes
const fs = require('fs');
const params = $input.item.json;
const stamp = new Date().toISOString();

let motivo = params.error || params.restoreError || 'Error desconocido';
if (!motivo && params.exitCode !== 0) motivo = `pg_dump finalizó con código ${params.exitCode}`;
if (!motivo && !params.contentOk) motivo = `pg_restore --list falló o el dump no contiene objetos (exitCode=${params.restoreExitCode}, objetos=${params.objectCount})`;
if (!motivo) motivo = 'Error desconocido';

const report = {
  resultado: 'backup_fallido',
  filename: params.filename,
  backupPath: params.backupPath,
  fileSizeBytes: params.fileSizeBytes || 0,
  error: motivo,
  exitCode: params.exitCode,
  objetosEnDump: params.objectCount || 0,
  timestamp: stamp,
  startedAt: params.startedAt
};

console.error('[WF2] FALLO en backup:', JSON.stringify(report));

const gen = params.genOk ? 'OK' : 'FALLO';
const verif = params.isValid ? 'OK' : 'FALLO';
const contenido = params.contentOk ? `OK(objetos=${params.objectCount})` : `FALLO(exitCode=${params.restoreExitCode}, objetos=${params.objectCount || 0})`;

const line = `[${stamp}] resultado=backup_fallido | archivo=${report.filename} | gen=${gen} | verificacion_archivo=${verif} | contenido=${contenido} | error=${motivo}\n`;
let logWritten = false, logError = '';
try {
  fs.appendFileSync('/data/informes/backup-log.txt', line, 'utf8');
  logWritten = true;
} catch (e) {
  logError = String(e.message || e);
}

return [{ json: { ...report, gen, verif, contenido, logWritten, logError } }];
